import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.lnbZLl6b.js";const r="/projects/aquilifer/screenshots/rate-limiting-settings.png",s="/projects/aquilifer/screenshots/rate-limit-popup.png",f=JSON.parse('{"title":"Rate limiting","description":"","frontmatter":{},"headers":[],"relativePath":"docs/rate-limiting.md","filePath":"docs/rate-limiting.md","lastUpdated":1789939732000}'),n={name:"docs/rate-limiting.md"};function l(c,e,h,u,p,g){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="rate-limiting" tabindex="-1">Rate limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate limiting&quot;">​</a></h1><p>Rate limits protect <em>your</em> usage (your spend, your quota) regardless of which interface a connected site happens to use, or why it&#39;s calling. They back the &quot;connect once, then silent&quot; approval model: without a popup on every request, a limit is what stops a bug (or a determined site) from running up unexpected costs on your account.</p><h2 id="two-tiers" tabindex="-1">Two tiers <a class="header-anchor" href="#two-tiers" aria-label="Permalink to &quot;Two tiers&quot;">​</a></h2><ul><li><strong>Global limit</strong>: a cap on total requests from a site across every way it can talk to Aquilifer, combined. This exists specifically so a site can&#39;t work around a per-interface limit by spreading requests across different call types.</li><li><strong>Per-interface limit</strong>: a tighter cap on any single interface (the generic chat interface, or a specific provider&#39;s native interface) on top of the global one.</li></ul><p>A request is blocked if it exceeds <em>either</em> limit. Both are configurable (window length and request count) from the <strong>Rate limiting</strong> tab in settings, with sensible defaults out of the box.</p><p><img src="'+r+'" alt="The Rate limiting settings tab, showing the global and per-interface limits, the large-request warning threshold, the block-alert cooldown, and the notification/popup checkboxes"></p><p><a href="/projects/aquilifer/docs/popup">The toolbar popup</a> shows the current site&#39;s real standing against these limits at a glance: whichever tier (global or per-interface) is closest to blocking, not just the configured threshold, so you can see it&#39;s getting close before it actually happens.</p><h2 id="what-happens-when-a-request-is-blocked" tabindex="-1">What happens when a request is blocked <a class="header-anchor" href="#what-happens-when-a-request-is-blocked" aria-label="Permalink to &quot;What happens when a request is blocked&quot;">​</a></h2><ul><li>It fails immediately, without reaching the provider (no cost incurred).</li><li>It&#39;s logged to <a href="/projects/aquilifer/docs/history">History</a> like any other request, marked as blocked.</li><li>You can optionally turn on a browser notification and/or a popup when a block happens, so you notice if something&#39;s calling more than expected. Repeated blocks from the same site share a cooldown (15 seconds by default, configurable above) rather than alerting on every single retry.</li></ul><p><img src="'+s+'" alt="The &#39;Rate limit reached&#39; popup, naming the site that got blocked"></p><h2 id="a-note-for-large-requests" tabindex="-1">A note for large requests <a class="header-anchor" href="#a-note-for-large-requests" aria-label="Permalink to &quot;A note for large requests&quot;">​</a></h2><p>Separately from frequency, Aquilifer also flags (but doesn&#39;t block) unusually large requests: a non-blocking warning shown in your history, in case a site is sending far more text than you&#39;d expect.</p><h2 id="a-note-if-you-re-integrating-aquilifer-as-a-fallback" tabindex="-1">A note if you&#39;re integrating Aquilifer as a fallback <a class="header-anchor" href="#a-note-if-you-re-integrating-aquilifer-as-a-fallback" aria-label="Permalink to &quot;A note if you&#39;re integrating Aquilifer as a fallback&quot;">​</a></h2><p>If your own site calls Aquilifer only when your primary integration is unavailable, treat a rate-limit failure as a hard stop, not something to retry aggressively: the limit is the <em>user&#39;s own</em> usage cap, not a transient error on your end. See <a href="/projects/aquilifer/docs/api">the page-facing API</a> for the specific error code to check for.</p>',14)])])}const m=t(n,[["render",l]]);export{f as __pageData,m as default};
